import { existsSync } from "node:fs";
import { expect, test } from "@playwright/test";

// Generated by the opt-in, billable long-summary eval. No customer data.
test.skip(
  !existsSync(".tmp/summary-100-pages.json"),
  "Run the synthetic 100-page evaluation first.",
);
test("renders summary visuals and preserves the app through print cleanup", async ({
  page,
}, info) => {
  await page.goto("/dev/summary-preview");
  await expect(page.getByRole("heading", { name: "100쪽 자료 요약 · 출력 검증" })).toBeVisible();
  expect(await page.locator(".summary-table").count()).toBeGreaterThan(0);
  expect(await page.locator(".summary-flow").count()).toBeGreaterThan(0);
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(
    true,
  );
  await page.screenshot({ path: `.tmp/summary-${info.project.name}.png` });
  // Test the same clone/cleanup event path without opening the operating-system dialog.
  await page.evaluate(() => {
    window.print = () => {};
  });
  await page.getByRole("button", { name: "요약을 PDF로 저장" }).click();
  await expect(page.locator("[data-summary-print-copy]")).toHaveCount(1);
  await expect(page.locator("main .arch-print-target")).toHaveCount(1);
  if (info.project.name === "laptop-1280") {
    await page.emulateMedia({ media: "print" });
    await page.pdf({
      path: "output/pdf/summary-100-pages.pdf",
      format: "A4",
      printBackground: true,
      preferCSSPageSize: true,
    });
    await page.emulateMedia({ media: "screen" });
  }
  await page.evaluate(() => window.dispatchEvent(new Event("afterprint")));
  await expect(page.locator("[data-summary-print-copy]")).toHaveCount(0);
  await expect(page.locator("main .arch-print-target")).toBeVisible();
  await expect(page.locator("body")).not.toHaveClass(/arch-printing/);
});
